446   bool replacement = m_ft_pending.request == mf;
447   if (replacement) {
448     ft_replacement &p = m_ft_pending;
449     assert(p.tag_index == index && probe == MISS);
450     if (p.dirty && m_config.m_ep_l2_ft_mode == 1) {
451       // A shared, explicitly costed 128B copy-pipeline latch bridges same-bank
452       // read and write cycles. Both compared organizations include this latch.
453       if (p.phase == 0) {
454         m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(p.victim,
455             false, physical_cycle, (unsigned long long)-1, ep_l2_payload_store::WB_READOUT,ep_l2_payload_store::COPY_READ,mf->get_request_uid());
456         if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
457           ++m_ft_stats.bank_block; return RESERVATION_FAIL;
458         }
459         p.born = physical_cycle; // actual source readout starts data-staging lifetime
460         p.copy_versions = m_ep_l2_payload.inspect(p.victim).versions;
461         p.phase = 1;
462         // COPY_FREE explicitly removes copy service and its staging delay.
463         // DATA_FREE removes port contention but retains this fixed one-cycle
464         // copy-latch transfer, even when source and target banks differ.
465         if (!m_config.m_ep_l2_diag_copy_free) return RESERVATION_FAIL;
466       }
467       if (p.phase == 1) {
468         m_ep_l2_last_payload_request_result = m_ep_l2_payload.request(p.staging,
469             true, physical_cycle, (unsigned long long)-1, ep_l2_payload_store::RESIDENT_WRITE,ep_l2_payload_store::COPY_WRITE,mf->get_request_uid());
470         if (m_ep_l2_last_payload_request_result != ep_l2_payload_store::GRANTED) {
471           ++m_ft_stats.bank_block; return RESERVATION_FAIL;
472         }
473         m_ep_l2_payload.inspect_mutable(p.staging).versions = p.copy_versions;
474         m_ep_l2_payload.transfer(p.staging, ep_l2_payload_store::WB, ep_l2_payload_store::WB_STAGED);
475         ++m_ft_stats.copy_lines; p.phase = 2;
